css:
.fx-ich{width:min(860px,100%);display:grid;gap:1.6em;text-align:center}
.fx-ich h2{font-size:clamp(1.7em,4vw,2.4em)}.fx-ich .sub{opacity:.6;margin-top:-1em}
.fx-ich .g{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:1em}
.fx-ich .t{display:grid;justify-items:center;gap:.8em;padding:1.6em .6em 1.2em;border:1px solid var(--border);border-radius:var(--radius);background:color-mix(in srgb,var(--surface) 94%,var(--text));color:var(--primary);text-decoration:none;transition:background calc(.3s/var(--speed)),color calc(.3s/var(--speed)),transform calc(.3s/var(--speed)) cubic-bezier(.2,.8,.2,1),border-color calc(.3s/var(--speed))}
.fx-ich .t svg{width:2.4em;height:2.4em;overflow:visible}
.fx-ich .t span{font-size:.85em;font-weight:700;color:var(--text);opacity:.75;transition:color .3s}
.fx-ich .t:hover,.fx-ich .t:focus-visible{background:var(--primary);color:var(--on-primary);transform:translateY(-4px);border-color:var(--primary)}
.fx-ich .t:hover span,.fx-ich .t:focus-visible span{color:var(--on-primary);opacity:1}
.fx-ich .t:focus-visible{outline:2px solid var(--accent);outline-offset:3px}
.fx-ich .sw,.fx-ich .fl,.fx-ich .dr,.fx-ich .t svg path,.fx-ich .t svg circle{transform-box:fill-box}
.fx-ich .t1 .sw{transform-origin:50% 10%}.fx-ich .t1:hover .sw{animation:fxichring calc(.7s/var(--speed)) ease}
.fx-ich .t2 path{transform-origin:center;transition:fill calc(.3s/var(--speed)),transform calc(.4s/var(--speed)) cubic-bezier(.3,1.8,.5,1)}.fx-ich .t2:hover path{fill:var(--accent);stroke:var(--accent);transform:scale(1.18)}
.fx-ich .t3 .fl{transform-origin:50% 0;transition:transform calc(.35s/var(--speed))}.fx-ich .t3:hover .fl{transform:scaleY(-.9) translateY(-1px)}
.fx-ich .t4 .sw{transform-origin:center;transition:transform calc(.8s/var(--speed)) cubic-bezier(.3,.7,.3,1)}.fx-ich .t4:hover .sw{transform:rotate(180deg)}
.fx-ich .t5 .sw{transition:transform calc(.3s/var(--speed)) cubic-bezier(.2,.8,.2,1)}.fx-ich .t5:hover .sw{transform:translateX(5px)}
.fx-ich .t6:hover .sw{animation:fxichdl calc(.8s/var(--speed)) ease infinite}
.fx-ich .t7 .sw{transform-origin:center;transition:transform calc(.35s/var(--speed)) cubic-bezier(.3,1.6,.5,1)}.fx-ich .t7:hover .sw{transform:scale(1.18) rotate(-12deg)}
.fx-ich .t8 .dr{stroke-dasharray:1;stroke-dashoffset:0}.fx-ich .t8:hover .dr{animation:fxichdraw calc(.6s/var(--speed)) ease}
@keyframes fxichring{15%{transform:rotate(16deg)}35%{transform:rotate(-14deg)}55%{transform:rotate(9deg)}75%{transform:rotate(-5deg)}to{transform:none}}
@keyframes fxichdl{0%,100%{transform:translateY(0)}50%{transform:translateY(3px)}}
@keyframes fxichdraw{from{stroke-dashoffset:1}to{stroke-dashoffset:0}}
@media(max-width:640px){.fx-ich .g{grid-template-columns:repeat(2,1fr)}}
@media(prefers-reduced-motion:reduce){.fx-ich .t,.fx-ich .t *{transition:none!important;animation:none!important}}

/* touch: :hover mirrored as .is-tap */
.fx-ich .t.is-tap{background:var(--primary);color:var(--on-primary);transform:translateY(-4px);border-color:var(--primary)}
.fx-ich .t.is-tap span{color:var(--on-primary);opacity:1}
.fx-ich .t1.is-tap .sw{animation:fxichring calc(.7s/var(--speed)) ease}
.fx-ich .t2.is-tap path{fill:var(--accent);stroke:var(--accent);transform:scale(1.18)}
.fx-ich .t3.is-tap .fl{transform:scaleY(-.9) translateY(-1px)}
.fx-ich .t4.is-tap .sw{transform:rotate(180deg)}
.fx-ich .t5.is-tap .sw{transform:translateX(5px)}
.fx-ich .t6.is-tap .sw{animation:fxichdl calc(.8s/var(--speed)) ease infinite}
.fx-ich .t7.is-tap .sw{transform:scale(1.18) rotate(-12deg)}
.fx-ich .t8.is-tap .dr{animation:fxichdraw calc(.6s/var(--speed)) ease}
